// ---- リール ----

type slotgame_reel struct {
	strip    []uint8 // リール配列
	offset   int     // 0 .. len(strip)*symH-1。増えると図柄が下に流れる
	spinning bool
	stopping bool
	remain   int // 停止までに進む残りピクセル
}

func (r *slotgame_reel) total() int { return len(r.strip) * slotgame_symH }

func (r *slotgame_reel) start() {
	r.spinning = true
	r.stopping = false
	r.remain = 0
}

// requestStop は次のコマ境界で止まるよう停止要求を出す（最大1コマ滑り）。
func (r *slotgame_reel) requestStop() {
	if !r.spinning || r.stopping {
		return
	}
	r.stopping = true
	r.remain = (slotgame_symH - r.offset%slotgame_symH) % slotgame_symH
}

// update は1フレーム分進め、描き直しが必要なら true を返す。
func (r *slotgame_reel) update() bool {
	if !r.spinning {
		return false
	}
	step := slotgame_spinSpeed
	if r.stopping {
		step = min(slotgame_spinSpeed, r.remain)
		r.remain -= step
	}
	r.offset = (r.offset + step) % r.total()
	if r.stopping && r.remain == 0 {
		r.spinning = false
		r.stopping = false
	}
	return true
}

// center は中段の図柄を返す（停止中のみ意味がある）。
func (r *slotgame_reel) center() uint8 {
	t := r.total()
	return r.strip[((slotgame_symH-r.offset)%t+t)%t/slotgame_symH]
}

// render はリールの見えている部分を buf（コマ幅×150）に描く。
func (r *slotgame_reel) render(buf pixel.Image[pixel.RGB565BE], syms *[slotgame_numSymbols]pixel.Image[pixel.RGB565BE]) {
	w, _ := buf.Size()
	rowBytes := w * 2
	dst := buf.RawBuffer()
	t := r.total()
	for y := 0; y < slotgame_reelH; y++ {
		s := ((y-r.offset)%t + t) % t
		src := syms[r.strip[s/slotgame_symH]].RawBuffer()
		row := s % slotgame_symH
		copy(dst[y*rowBytes:(y+1)*rowBytes], src[row*rowBytes:(row+1)*rowBytes])
	}
	v := pixel.NewColor[pixel.RGB565BE](slotgame_colLine.R, slotgame_colLine.G, slotgame_colLine.B)
	for _, y := range [2]int{slotgame_symH - 1, slotgame_symH * 2} {
		line := dst[y*rowBytes : (y+1)*rowBytes]
		for x := 0; x < rowBytes; x += 2 {
			line[x] = byte(v)
			line[x+1] = byte(v >> 8)
		}
	}
}

