// judge は中段の3図柄から配当とメッセージを返す。上から順に最初に当てはまった役のみ。
func slotgame_judge(l, c, r uint8) (int, string) {
	switch {
	case l == slotgame_symSeven && c == slotgame_symSeven && r == slotgame_symSeven:
		return 100, "BIG BONUS!! +100"
	case l == slotgame_symBar && c == slotgame_symBar && r == slotgame_symBar:
		return 50, "BAR BAR BAR! +50"
	case l == slotgame_symTinyGo && c == slotgame_symTinyGo && r == slotgame_symTinyGo:
		return 25, "TINYGO!! +25"
	case l == slotgame_symBell && c == slotgame_symBell && r == slotgame_symBell:
		return 15, "BROWN GOPHER +15"
	case l == slotgame_symCherry && c == slotgame_symCherry && r == slotgame_symCherry:
		return 10, "CHERRY x3 +10"
	case l == slotgame_symGrape && c == slotgame_symGrape && r == slotgame_symGrape:
		return 8, "BLUE GOPHER +8"
	case l == slotgame_symCherry:
		return 2, "CHERRY +2"
	}
	return 0, "PRESS SW1"
}

