type slotgame_game struct {
	scr       slotgame_screen
	lay       slotgame_layout
	oneButton bool // true ならボタン 1 つで、押すたびに左のリールから順に止める
	syms      [slotgame_numSymbols]pixel.Image[pixel.RGB565BE]
	reelImg   pixel.Image[pixel.RGB565BE]
	reels     [3]slotgame_reel
	state     int
	credit    int
	spinStart time.Time
}

func slotgame_newGame(scr slotgame_screen, lay slotgame_layout) *slotgame_game {
	g := &slotgame_game{scr: scr, lay: lay, credit: slotgame_startCredit}
	g.syms = slotgame_makeSymbols(lay.symW)
	g.reelImg = pixel.NewImage[pixel.RGB565BE](lay.symW, slotgame_reelH)
	for i := range g.reels {
		g.reels[i].strip = slotgame_strips[i]
	}
	g.drawStatic()
	g.drawCredit()
	for i := range g.reels {
		g.drawReel(i)
	}
	g.drawLabels()
	g.drawMessage("PRESS SW1", slotgame_colYellow)
	return g
}

// edges は押された瞬間（前フレームで離されていて、今フレームで押されている）だけを true にする。
// フレーム周期でサンプリングするので、チャタリング対策も兼ねる。
func slotgame_edges(down [3]bool, prev *[3]bool) [3]bool {
	var pressed [3]bool
	for i := range down {
		pressed[i] = down[i] && !prev[i]
	}
	*prev = down
	return pressed
}

// step は1フレーム分の処理。pressed は各ボタンがこのフレームで押された瞬間かどうか。
func (g *slotgame_game) step(pressed [3]bool, now time.Time) {
	anyPressed := pressed[0] || pressed[1] || pressed[2]
	switch g.state {
	case slotgame_stateIdle:
		if !anyPressed {
			return
		}
		g.credit -= slotgame_bet
		g.drawCredit()
		g.clearMessage()
		g.spinStart = now
		for i := range g.reels {
			g.reels[i].start()
		}
		g.drawLabels()
		g.state = slotgame_stateSpinning

	case slotgame_stateSpinning:
		if now.Sub(g.spinStart) >= slotgame_stopLockout {
			if g.oneButton {
				if i := g.nextReel(); anyPressed && i >= 0 {
					g.reels[i].requestStop()
					g.drawLabels()
				}
			} else {
				for i, p := range pressed {
					if p {
						g.reels[i].requestStop()
					}
				}
			}
		}
		allStopped := true
		for i := range g.reels {
			r := &g.reels[i]
			wasSpinning := r.spinning
			if r.update() {
				g.drawReel(i)
			}
			if wasSpinning && !r.spinning {
				g.drawLabel(i)
			}
			if r.spinning {
				allStopped = false
			}
		}
		if allStopped {
			g.finishSpin()
		}

	case slotgame_stateGameOver:
		if !anyPressed {
			return
		}
		g.credit = slotgame_startCredit
		g.drawCredit()
		g.drawMessage("PRESS SW1", slotgame_colYellow)
		g.state = slotgame_stateIdle
	}
}

// nextReel は 1 ボタンのときに次に止めるリール（回転中で停止要求の出ていない一番左）を返す。無ければ -1。
func (g *slotgame_game) nextReel() int {
	for i := range g.reels {
		if g.reels[i].spinning && !g.reels[i].stopping {
			return i
		}
	}
	return -1
}

func (g *slotgame_game) finishSpin() {
	win, msg := slotgame_judge(g.reels[0].center(), g.reels[1].center(), g.reels[2].center())
	g.credit += win
	g.drawCredit()
	switch {
	case g.credit < slotgame_bet:
		g.drawMessage(g.lay.gameOver, slotgame_colRed)
		g.state = slotgame_stateGameOver
	case win > 0:
		g.drawMessage(msg, slotgame_colYellow)
		g.state = slotgame_stateIdle
	default:
		g.drawMessage(msg, slotgame_colWhite)
		g.state = slotgame_stateIdle
	}
}

// ---- 画面描画 ----

func (g *slotgame_game) drawStatic() {
	s, l := g.scr, &g.lay
	s.FillRectangle(0, 0, l.screenW, slotgame_screenH, slotgame_colBG)
	tinyfont.WriteLine(s, &freesans.Bold12pt7b, 8, 26, "SLOT", slotgame_colYellow)
	w := int16(l.symW)
	for _, x := range l.reelX {
		g.drawFrame(x-1, slotgame_reelY-1, w+2, slotgame_reelH+2)
		g.drawFrame(x-2, slotgame_reelY-2, w+4, slotgame_reelH+4)
	}
	// 有効ラインを指す内向きの三角マーカー
	for i := int16(0); i < l.markerW; i++ {
		h := l.markerW - 1 - i
		s.FillRectangle(l.markerX+i, slotgame_markerCY-h, 1, 2*h+1, slotgame_colLine)
		s.FillRectangle(l.screenW-1-l.markerX-i, slotgame_markerCY-h, 1, 2*h+1, slotgame_colLine)
	}
}

// drawFrame は 1px の枠を描く。
func (g *slotgame_game) drawFrame(x, y, w, h int16) {
	s := g.scr
	s.FillRectangle(x, y, w, 1, slotgame_colFrame)
	s.FillRectangle(x, y+h-1, w, 1, slotgame_colFrame)
	s.FillRectangle(x, y, 1, h, slotgame_colFrame)
	s.FillRectangle(x+w-1, y, 1, h, slotgame_colFrame)
}

func (g *slotgame_game) drawCredit() {
	s, sw := g.scr, g.lay.screenW
	// 右寄せの「CREDIT n」を消す範囲。左の「SLOT」にはかからないようにする。
	_, tw := tinyfont.LineWidth(&freesans.Bold12pt7b, "SLOT")
	x := max(sw-170, 8+int16(tw)+4)
	s.FillRectangle(x, 4, sw-x, 30, slotgame_colBG)
	str := "CREDIT " + strconv.Itoa(g.credit)
	_, w := tinyfont.LineWidth(&freesans.Bold12pt7b, str)
	tinyfont.WriteLine(s, &freesans.Bold12pt7b, sw-8-int16(w), 26, str, slotgame_colWhite)
}

func (g *slotgame_game) clearMessage() {
	g.scr.FillRectangle(0, slotgame_msgY, g.lay.screenW, slotgame_msgH, slotgame_colBG)
}

func (g *slotgame_game) drawMessage(msg string, col color.RGBA) {
	g.clearMessage()
	_, w := tinyfont.LineWidth(&freesans.Bold9pt7b, msg)
	tinyfont.WriteLine(g.scr, &freesans.Bold9pt7b, (g.lay.screenW-int16(w))/2, 213, msg, col)
}

func (g *slotgame_game) drawReel(i int) {
	g.reels[i].render(g.reelImg, &g.syms)
	g.scr.DrawBitmap(g.lay.reelX[i], slotgame_reelY, g.reelImg)
}

func (g *slotgame_game) drawLabels() {
	for i := range g.reels {
		g.drawLabel(i)
	}
}

// drawLabel は SW1 ラベルを描く。回転中は赤、停止中は灰。
// 1 ボタンのときは、次に止まるリールだけを赤にし、順番待ちのリールは暗い赤、
// 停止要求を出したリールは灰にする。
func (g *slotgame_game) drawLabel(i int) {
	bg, fg := slotgame_colGray, slotgame_colBG
	switch r := &g.reels[i]; {
	case !r.spinning, g.oneButton && r.stopping:
	case g.oneButton && i != g.nextReel():
		bg, fg = slotgame_colDarkRed, slotgame_colGray
	default:
		bg, fg = slotgame_colRed, slotgame_colWhite
	}
	x, w := g.lay.reelX[i], int16(g.lay.symW)
	g.scr.FillRectangle(x, slotgame_labelY, w, slotgame_labelH, bg)
	const label = "SW1"
	_, tw := tinyfont.LineWidth(&freesans.Bold9pt7b, label)
	tinyfont.WriteLine(g.scr, &freesans.Bold9pt7b, x+(w-int16(tw))/2, 236, label, fg)
}
